  "steps": [
    {
      "id": 1,
      "claim": "Einstein's photoelectric equation states that the maximum kinetic energy of emitted electrons is the difference between the photon energy and the work function.",
      "evidence": "The equation is $K_{max} = hf - \\phi$, where $h$ is Planck's constant, $f$ is frequency, and $\\phi$ is the work function.",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The stopping potential is directly proportional to the maximum kinetic energy of the emitted electrons.",
      "evidence": "The work done by the electric field to stop the electrons equals their initial kinetic energy: $K_{max} = eV_s$, where $e$ is the elementary charge and $V_s$ is the stopping potential.",
      "weight": 0.25,
      "depends_on": [
        1
      ]
    },
    {
      "id": 3,
      "claim": "The stopping potential is a linear function of the incident frequency.",
      "evidence": "Substituting $K_{max}$ from step 1 into step 2 yields $eV_s = hf - \\phi$, which rearranges to $V_s = (h/e)f - \\phi/e$. This is a linear equation of the form $y = mx + b$ with slope $h/e$ and intercept $-\\phi/e$.",
      "weight": 0.3,
      "depends_on": [
        1,
        2
      ]
    },
    {
      "id": 4,
      "claim": "The linear relationship is valid only for frequencies above the threshold frequency.",
      "evidence": "Electrons are emitted only if the photon energy exceeds the work function ($hf > \\phi$), meaning $f > f_0 = \\phi/h$. Below this threshold, no electrons are emitted, and the stopping potential is not defined in the context of stopping emitted current.",
      "weight": 0.2,
      "depends_on": [
        1
      ]
    }
  ],
